56	/* Test longest possible handshake interaction (7 messages):
57	 *
58	 * 1. I -> R (initiation)
59	 * 2. I <- R (cookie reply)
60	 * 3. I -> R (initiation)
61	 * 4. I <- R (response)
62	 * 5. I -> R (cookie reply)
63	 * 6. I -> R (initiation)
64	 * 7. I <- R (response)
65	 */
66	#[test]
67	fn handshake_under_load() {
68	    let (_pk1, dev1, pk2, dev2): (_, Device<usize>, _, _) =
69	        setup_devices(&mut OsRng, &mut OsRng, &mut OsRng);
70	
71	    let src1: SocketAddr = "172.16.0.1:8080".parse().unwrap();
72	    let src2: SocketAddr = "172.16.0.2:7070".parse().unwrap();
73	
74	    // 1. device-1 : create first initiation
75	    let msg_init = dev1.begin(&mut OsRng, &pk2).unwrap();
76	
77	    // 2. device-2 : responds with CookieReply
78	    let msg_cookie = match dev2.process(&mut OsRng, &msg_init, Some(src1)).unwrap() {
79	        (None, Some(msg), None) => msg,
80	        _ => panic!("unexpected response"),
81	    };
82	
83	    // device-1 : processes CookieReply (no response)
84	    match dev1.process(&mut OsRng, &msg_cookie, Some(src2)).unwrap() {
85	        (None, None, None) => (),
86	        _ => panic!("unexpected response"),
87	    }
88	
89	    // avoid initiation flood detection
90	    wait();
91	
92	    // 3. device-1 : create second initiation
93	    let msg_init = dev1.begin(&mut OsRng, &pk2).unwrap();
94	
95	    // 4. device-2 : responds with noise response
96	    let msg_response = match dev2.process(&mut OsRng, &msg_init, Some(src1)).unwrap() {
97	        (Some(_), Some(msg), Some(kp)) => {
98	            assert_eq!(kp.initiator, false);
99	            msg
100	        }
101	        _ => panic!("unexpected response"),
102	    };
103	
104	    // 5. device-1 : responds with CookieReply
105	    let msg_cookie = match dev1.process(&mut OsRng, &msg_response, Some(src2)).unwrap() {
106	        (None, Some(msg), None) => msg,
107	        _ => panic!("unexpected response"),
108	    };
109	
110	    // device-2 : processes CookieReply (no response)
111	    match dev2.process(&mut OsRng, &msg_cookie, Some(src1)).unwrap() {
112	        (None, None, None) => (),
113	        _ => panic!("unexpected response"),
114	    }
115	
116	    // avoid initiation flood detection
117	    wait();
118	
119	    // 6. device-1 : create third initiation
120	    let msg_init = dev1.begin(&mut OsRng, &pk2).unwrap();
121	
122	    // 7. device-2 : responds with noise response
123	    let (msg_response, kp1) = match dev2.process(&mut OsRng, &msg_init, Some(src1)).unwrap() {
124	        (Some(_), Some(msg), Some(kp)) => {
125	            assert_eq!(kp.initiator, false);
126	            (msg, kp)
127	        }
128	        _ => panic!("unexpected response"),
129	    };
130	
131	    // device-1 : process noise response
132	    let kp2 = match dev1.process(&mut OsRng, &msg_response, Some(src2)).unwrap() {
133	        (Some(_), None, Some(kp)) => {
134	            assert_eq!(kp.initiator, true);
135	            kp
136	        }
137	        _ => panic!("unexpected response"),
138	    };
139	
140	    assert_eq!(kp1.send, kp2.recv);
141	    assert_eq!(kp1.recv, kp2.send);
142	}
