144	#[test]
145	fn handshake_no_load() {
146	    let (pk1, mut dev1, pk2, mut dev2): (_, Device<usize>, _, _) =
147	        setup_devices(&mut OsRng, &mut OsRng, &mut OsRng);
148	
149	    // do a few handshakes (every handshake should succeed)
150	
151	    for i in 0..10 {
152	        println!("handshake : {}", i);
153	
154	        // create initiation
155	
156	        let msg1 = dev1.begin(&mut OsRng, &pk2).unwrap();
157	
158	        println!("msg1 = {} : {} bytes", hex::encode(&msg1[..]), msg1.len());
159	        println!(
160	            "msg1 = {:?}",
161	            Initiation::parse(&msg1[..]).expect("failed to parse initiation")
162	        );
163	
164	        // process initiation and create response
165	
166	        let (_, msg2, ks_r) = dev2
167	            .process(&mut OsRng, &msg1, None)
168	            .expect("failed to process initiation");
169	
170	        let ks_r = ks_r.unwrap();
171	        let msg2 = msg2.unwrap();
172	
173	        println!("msg2 = {} : {} bytes", hex::encode(&msg2[..]), msg2.len());
174	        println!(
175	            "msg2 = {:?}",
176	            Response::parse(&msg2[..]).expect("failed to parse response")
177	        );
178	
